-- Somente leitura: consulta usada para extrair o contrato do prover PG17.
select jsonb_build_object('tables',(select jsonb_object_agg(table_name,ddl) from (select c.relname as table_name,'CREATE TABLE public.'||quote_ident(c.relname)||E' (\n'||(select string_agg('  '||quote_ident(a.attname)||' '||pg_catalog.format_type(a.atttypid,a.atttypmod)||case when a.attidentity='a' then ' GENERATED ALWAYS AS IDENTITY' when a.attidentity='d' then ' GENERATED BY DEFAULT AS IDENTITY' when d.adbin is not null then ' DEFAULT '||pg_get_expr(d.adbin,d.adrelid) else '' end||case when a.attnotnull then ' NOT NULL' else '' end,E',\n' order by a.attnum) from pg_attribute a left join pg_attrdef d on a.attrelid=d.adrelid and a.attnum=d.adnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)||E'\n);\n'||coalesce((select string_agg('ALTER TABLE public.'||quote_ident(c.relname)||' ADD CONSTRAINT '||quote_ident(con.conname)||' '||pg_get_constraintdef(con.oid)||';',E'\n' order by con.conname) from pg_constraint con where con.conrelid=c.oid),'') as ddl from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('candidatos','coleta_log'))t),'view',pg_get_viewdef('public.candidatos_publico'::regclass,true)) as schema_contract;
